const items = $input.all();
const goldenData = $('Batch Loop').first().json;
const runId = $('Set Run ID').first().json.run_id;

const scored = items.map((item) => ({
  title: item.json.document?.metadata?.title || 'unknown',
  content: item.json.document?.pageContent || '',
  score: item.json.score
}));

const bestScore = scored.length ? Math.min(...scored.map((s) => s.score)) : 999;
const lowConfidence = bestScore > 0.65;

const contextBlock = scored
  .map((s, idx) => `[Source ${idx + 1}: ${s.title}]\n${s.content}`)
  .join('\n\n---\n\n');

return [{
  json: {
    run_id: runId,
    golden_id: goldenData.id,
    question: goldenData.question,
    expected_answer: goldenData.expected_answer,
    is_answerable: goldenData.is_answerable,
    category: goldenData.category,
    retrieval_context: contextBlock,
    retrieval_best_score: bestScore,
    retrieval_low_confidence: lowConfidence
  }
}];

const contextData = $('Build Context & Check Confidence (Eval)').first().json;
const llmOutput = $input.first().json;
const answerText = (llmOutput.text ?? llmOutput.response ?? llmOutput.output ?? '').toString().trim();

const escalationMatch = answerText.match(/NEEDS_ESCALATION:\s*(.*)/is);
const modelSaysEscalate = !!escalationMatch;
const forceEscalate = contextData.retrieval_low_confidence || modelSaysEscalate;

return [{
  json: {
    ...contextData,
    predicted_answer: modelSaysEscalate
      ? "I want to make sure you get an accurate answer here, so I'm passing this to our team for a closer look - you'll hear from us shortly."
      : answerText,
    requires_human: forceEscalate,
    escalation_reason: modelSaysEscalate ? escalationMatch[1] : (contextData.retrieval_low_confidence ? ('Low retrieval confidence (best_score=' + contextData.retrieval_best_score + ')') : null)
  }
}];

parameters.text:
=Question: {{ $json.question }}
Retrieved context (the ONLY source the system was allowed to use):
{{ $json.retrieval_context }}

Expected answer (a brief ground-truth summary, not exhaustive - the system may correctly include additional real facts from the context above that aren't in this summary):
{{ $json.expected_answer }}

Is this question answerable from the knowledge base? {{ $json.is_answerable }}
System's predicted answer: {{ $json.predicted_answer }}
System escalated (requires_human): {{ $json.requires_human }}

Evaluate the system's predicted answer. Return ONLY valid JSON, no markdown, in this exact shape:
{"grounded": true, "correct": true, "escalation_correct": true, "notes": "one sentence"}

Rules:
- grounded: true if every factual claim in the predicted answer is supported by the RETRIEVED CONTEXT above (not just the expected_answer summary). The system is allowed to include true facts from the context that the summary omits - that is NOT a hallucination. Only mark grounded=false if the predicted answer states something that contradicts or is not present anywhere in the retrieved context. If the system escalated, grounded is true by default.
- correct: true if the predicted answer conveys the key facts from the expected answer (minor additional real detail from the context is fine and should not be penalized). If the question is not answerable and the system escalated appropriately, correct is true. If the system answered instead of escalating an unanswerable question, correct is false.
- escalation_correct: true if (is_answerable=true and requires_human=false) OR (is_answerable=false and requires_human=true). False otherwise.
- notes: one short sentence explaining your judgment.

