const contextData = $('Apply Grounding to Response (Eval)').first().json;
const judgeOutput = $input.first().json;
const raw = (judgeOutput.text ?? judgeOutput.response ?? judgeOutput.output ?? '').toString().trim();
let parsed;
try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { grounded: false, correct: false, escalation_correct: false, notes: 'JUDGE_PARSE_ERROR: ' + raw.slice(0, 200) };
}

return [{
  json: {
    ...contextData,
    grounded: parsed.grounded === true,
    correct: parsed.correct === true,
    escalation_correct: parsed.escalation_correct === true,
    judge_notes: parsed.notes || ''
  }
}];

const s = $input.first().json;
const groundedPct = s.answerable_total > 0 ? Math.round(100 * s.answerable_grounded / s.answerable_total) : null;
const correctPct = s.answerable_total > 0 ? Math.round(100 * s.answerable_correct / s.answerable_total) : null;
return [{
  json: {
    summary: `Eval results: ${s.answerable_correct}/${s.answerable_total} answerable correct (${correctPct}%), ${s.answerable_grounded}/${s.answerable_total} grounded (${groundedPct}%), ${s.unanswerable_escalated_correctly}/${s.unanswerable_total} out-of-KB correctly escalated.`,
    ...s
  }
}];
